jsonBlocks.content:
terraform {
  required_version = ">= 1.10.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}

provider "aws" {
  region  = var.aws_region
}

resource "aws_vpc" "lab" {
  cidr_block           = "10.40.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = { Name = "fa-tf-beginner-vpc", ManagedBy = "Terraform" }
}

resource "aws_subnet" "lab" {
  vpc_id                  = aws_vpc.lab.id
  cidr_block              = "10.40.1.0/24"
  map_public_ip_on_launch = false
  tags = { Name = "fa-tf-beginner-subnet", ManagedBy = "Terraform" }
}

resource "aws_security_group" "lab" {
  name        = "fa-tf-beginner-sg"
  description = "No-ingress comparison security group"
  vpc_id      = aws_vpc.lab.id
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = { Name = "fa-tf-beginner-sg", ManagedBy = "Terraform" }
}

variable "aws_region" {
  description = "AWS Region for regional lab resources"
  type        = string
  default     = "eu-west-2"
}

output "vpc_id" { value = aws_vpc.lab.id }
output "subnet_id" { value = aws_subnet.lab.id }
output "security_group_id" { value = aws_security_group.lab.id }

variable "name" { type = string }
variable "cidr" { type = string }

resource "aws_vpc" "this" {
  cidr_block           = var.cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = { Name = var.name, ManagedBy = "Terraform" }
}

output "id" { value = aws_vpc.this.id }

terraform {
  required_version = ">= 1.10.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

module "vpc" {
  source = "./modules/vpc"
  name   = "fa-tf-beginner-vpc"
  cidr   = "10.40.0.0/16"
}

moved {
  from = aws_vpc.lab
  to   = module.vpc.aws_vpc.this
}

resource "aws_subnet" "lab" {
  vpc_id                  = module.vpc.id
  cidr_block              = "10.40.1.0/24"
  map_public_ip_on_launch = false
  tags = { Name = "fa-tf-beginner-subnet", ManagedBy = "Terraform" }
}

resource "aws_security_group" "lab" {
  name        = "fa-tf-beginner-sg"
  description = "No-ingress beginner security group"
  vpc_id      = module.vpc.id
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = { Name = "fa-tf-beginner-sg", ManagedBy = "Terraform" }
}

output "vpc_id" { value = module.vpc.id }
output "subnet_id" { value = aws_subnet.lab.id }
output "security_group_id" { value = aws_security_group.lab.id }
